from __future__ import annotationsfrom pathlib import Pathfrom sklearn.datasets import load_irisfrom sklearn.model_selection import train_test_splitimport joblibfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import accuracy_score, f1_scorefrom ml_service.config import load_configdef train():    config = load_config()    data = load_iris(as_frame=True)    features = data.data    features.columns = config.feature_names    target = data.target    X_train, X_test, y_train, y_test = train_test_split(        features, target, test_size=0.2, random_state=42, stratify=target    )    print("train rows:", len(X_train), "| test rows:", len(X_test))    print(features.head())    model = RandomForestClassifier(n_estimators=200, max_depth=4, random_state=42)    model.fit(X_train, y_train)    predictions = model.predict(X_test)    accuracy = accuracy_score(y_test, predictions)    f1 = f1_score(y_test, predictions, average="macro")    print(f"accuracy: {accuracy:.3f} | f1_macro: {f1:.3f}")    Path(config.model_path).parent.mkdir(parents=True, exist_ok=True)    joblib.dump(model, config.model_path)    print(f"saved model -> {config.model_path}")        X_train.to_csv(config.reference_data_path, index=False)    print(f"saved reference -> {config.reference_data_path}")if __name__ == "__main__":    train()